package org.geotools.ysld;

import org.yaml.snakeyaml.DumperOptions;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import org.yaml.snakeyaml.representer.Representer;

/** Factory for Yaml instances. */
public class YamlUtil {

    public static class YsldConstructorException extends org.yaml.snakeyaml.constructor.ConstructorException {
        public YsldConstructorException(String context, org.yaml.snakeyaml.error.Mark contextMark, String problem, org.yaml.snakeyaml.error.Mark problemMark) {
            super(context, contextMark, problem, problemMark);
        }
    }

    public static Yaml getSafeYaml() {
        return getSafeYaml(new DumperOptions());
    }

    public static Yaml getSafeYaml(DumperOptions dumperOptions) {
        return getSafeYaml(new Representer(dumperOptions), dumperOptions);
    }

    public static Yaml getSafeYaml(Representer representer, DumperOptions dumperOptions) {
        return new Yaml(new SafeConstructor(new LoaderOptions()), representer, dumperOptions) {
            @Override
            public <T> T load(String yaml) {
                try {
                    return super.load(yaml);
                } catch (org.yaml.snakeyaml.composer.ComposerException e) {
                    throw translateComposerException(e);
                }
            }

            @Override
            public <T> T load(java.io.InputStream in) {
                try {
                    return super.load(in);
                } catch (org.yaml.snakeyaml.composer.ComposerException e) {
                    throw translateComposerException(e);
                }
            }

            @Override
            public <T> T load(java.io.Reader reader) {
                try {
                    return super.load(reader);
                } catch (org.yaml.snakeyaml.composer.ComposerException e) {
                    throw translateComposerException(e);
                }
            }
        };
    }

    private static RuntimeException translateComposerException(org.yaml.snakeyaml.composer.ComposerException e) {
        String problem = e.getProblem();
        if (problem != null && problem.contains("Global tag is not allowed:")) {
            String tag = problem.substring(problem.indexOf("Global tag is not allowed:") + "Global tag is not allowed:".length()).trim();
            return new YsldConstructorException(
                e.getContext(),
                e.getContextMark(),
                "could not determine a constructor for the tag " + tag,
                e.getProblemMark()
            );
        }
        return e;
    }
}
